return JSON.stringify(value, (key, value) => {
  if (typeof value === 'object' && value !== null) {
    if (Array.isArray(value)) {
      return value;
    }
    const sortedKeys = Object.keys(value).sort();
    const result: { [k: string]: any } = {};
    for (const k of sortedKeys) {
      result[k] = value[k];
    }
    return result;
  }
  return value;
});
